const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(v,d=3)=>v==null?'—':Number(v).toFixed(d),table=(heads,rows)=>'<table><thead><tr>'+heads.map(v=>'<th>'+esc(v)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
let A,E,paired=[];const query=new URLSearchParams(location.search);
const sourceLinks=ids=>'<div class="sources">'+ids.map(id=>{const s=E.sources[id];return s?`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} · ${esc(s.date)} ↗</a><span>${esc(s.scope)}</span>`:'';}).join('')+'</div>';
function matrix(){const years=+$('years').value;const codes=Object.keys(A.stocks);$('matrix').innerHTML=table(['지표',...codes.map(c=>A.stocks[c])],Object.values(A.indicators).map(i=>[esc(i.name),...codes.map(c=>{const s=A.summary.find(s=>s.indicator===i.id&&s.stock===c&&s.years===years),r=years===1?s?.contemporaneous?.r:s?.contemporaneous?.partialR;return `<button data-i="${i.id}" data-s="${c}" title="${esc(s?.status)}" style="background:rgba(37,99,235,${r==null?0:.07+Math.abs(r)*.55})">${fmt(r,2)}</button>`;})]));$('matrix').querySelectorAll('button').forEach(b=>b.onclick=()=>{$('indicator').value=b.dataset.i;$('stock').value=b.dataset.s;pair();$('pair').scrollIntoView({behavior:'smooth'});});}
function pair(){const iid=$('indicator').value,code=$('stock').value,years=+$('years').value,info=A.indicators[iid],e=E.byPair[iid+':'+code];history.replaceState(null,'',`/analysis?indicator=${iid}&stock=${code}`);$('pair-title').textContent=info.name+' × '+A.stocks[code];$('evidence').innerHTML=e?`<span class="badge">${esc(e.status)} · 자료 ${e.sourceIds.length}개</span>${e.direction?`<p><b>지표 상승: ${esc(e.direction.up)} / 하락: ${esc(e.direction.down)}</b> · 조건부 실적 영향</p>`:""}<p>${esc(e.text)}</p><p><b>실적 반영 시점:</b> ${esc(e.lag)}</p>${e.notes.map(n=>'<p class="muted">'+esc(n)+'</p>').join('')}${sourceLinks(e.sourceIds)}`:'<p>이 조합은 기존 사업상 전달경로가 지정되지 않았습니다. 아래 수치는 전체 조합에 대한 통계 탐색이며 직접적인 실적 영향을 뜻하지 않습니다.</p>';
 const periods=A.summary.filter(s=>s.indicator===iid&&s.stock===code);$('periods').innerHTML=table(['기간','동월 n','동월 r / 부분상관','탐색 최대 시차','부분상관','β [95% 구간]','q','전후반 부호','판정'],periods.map(s=>{const b=s.best,z=s.contemporaneous;return[s.years+'년',z?.n??0,fmt(z?.r)+' / '+fmt(z?.partialR),b?b.lag+'개월':'—',fmt(b?.partialR),b?`${fmt(b.beta)} [${fmt(b.ciLow)}, ${fmt(b.ciHigh)}]`:'—',fmt(b?.q,4),b?(b.sameSignHalves?'일치':'미확인/불일치'):'—',esc(s.status)];}));
 const rs=A.results.filter(r=>r.indicator===iid&&r.stock===code&&r.years===years);$('lag-chart').innerHTML=rs.length?`<svg viewBox="0 0 850 200" role="img" aria-label="시차별 상관계수"><line x1="20" x2="830" y1="92" y2="92" stroke="#bccbde"/>${rs.map((r,j)=>{const v=years===1?r.r:r.partialR,x=25+j*42;return `<rect x="${x}" y="${v>0?92-v*80:92}" width="29" height="${Math.abs(v||0)*80}" fill="#2563eb"><title>${r.lag}개월: ${fmt(v)}, n=${r.n}</title></rect><text x="${x+14}" y="185" text-anchor="middle">${r.lag}</text>`;}).join('')}<text x="20" y="15">${years===1?'단순 상관 (소표본 참고)':'시장 통제 부분상관'} · +1 / 0 / −1 범위</text></svg>`:'<p class="empty">'+esc(info.reason||'유효 표본 부족')+'</p>';
 $('lags').innerHTML=table(['시차(월)','n','Pearson r','Spearman','부분상관','β','95% 하한','95% 상한','p','다중검정 q'],rs.map(r=>[r.lag,r.n,fmt(r.r),fmt(r.spearman),fmt(r.partialR),fmt(r.beta),fmt(r.ciLow),fmt(r.ciHigh),fmt(r.p,4),fmt(r.q,4)]));pairedTable();}
function pairedTable(){const iid=$('indicator').value,code=$('stock').value,L=+$('lag').value,N=+$('years').value*12,P=A.panel,start=P.months.length-N;paired=[];for(let y=start;y<P.months.length;y++){const x=y-L;if(x<start||x>=P.months.length)continue;const v=P.macro[iid]?.[x],r=P.stock[code]?.[y],m=P.market[y];if(v==null||r==null||m==null)continue;paired.push([P.months[x],P.months[y],v,r,m]);}$('transform').textContent=(A.indicators[iid].transform||A.indicators[iid].reason)+' · 지표 변환값과 월수익률의 실제 대응표 · '+paired.length+'행';$('paired').innerHTML=table(['지표 기준월','주가 수익률 월','지표 변화값','수정종가 수익률 (%)','KOSPI (%)'],paired.map(r=>r.map((v,i)=>i<2?v:fmt(v,4))));}
async function load(){const res=await fetch('/api/analysis');if(!res.ok)throw Error('분석 파일을 읽을 수 없습니다');({analysis:A,evidence:E}=await res.json());$('coverage').textContent=`${A.asOfMonth} 완료 월 기준 · ${A.indicatorCount}개 지표 × ${A.stockCount}개 종목 = ${A.indicatorCount*A.stockCount}개 조합 · 4개 기간 · ${A.estimableIndicators}개 지표 시차 계산 · ${A.hypothesisCount.toLocaleString()}개 회귀 다중검정`;
 $('indicator').innerHTML=Object.values(A.indicators).map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('');$('stock').innerHTML=Object.entries(A.stocks).map(([c,n])=>`<option value="${c}">${esc(n)}</option>`).join('');$('lag').innerHTML=A.method.lags.map(l=>`<option value="${l}" ${l===0?'selected':''}>${l}개월</option>`).join('');if(A.indicators[query.get('indicator')])$('indicator').value=query.get('indicator');if(A.stocks[query.get('stock')])$('stock').value=query.get('stock');$('years').onchange=()=>{matrix();pair();};$('indicator').onchange=pair;$('stock').onchange=pair;$('lag').onchange=pairedTable;
 $('paired-download').onclick=()=>{const blob=new Blob(['\uFEFF지표월,수익률월,지표변화값,수정종가수익률_pct,KOSPI_pct\n'+paired.map(r=>r.join(',')).join('\n')],{type:'text/csv;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`paired-${$('indicator').value}-${$('stock').value}-${$('years').value}y-lag${$('lag').value}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
 $('cases').innerHTML=E.cases.map(c=>`<article class="case"><h3>${esc(c.title)}</h3><span class="badge">${esc(c.type)}</span>${table(c.columns,c.rows.map(r=>r.map(esc)))}<p>${esc(c.conclusion)}</p>${sourceLinks(c.sourceIds)}</article>`).join('');$('method').innerHTML=`<p>${esc(A.method.model)}</p><p>${esc(A.method.returns)}</p><ul>${A.method.limits.map(l=>'<li>'+esc(l)+'</li>').join('')}</ul><p>${esc(E.policy)}</p><p class="sources">주가 원천: ${esc(A.priceSource)} · <a href="https://help.yahoo.com/kb/SLN28256.html" target="_blank" rel="noopener">수정종가 정의 ↗</a> · 월말 종가 대조: Naver Finance · 분석 생성 ${esc(A.generatedAt)}</p>`;$('quality').innerHTML=Object.entries(A.quality).map(([c,q])=>`<p><b>${esc(A.stocks[c])}</b> ${q.checkedMonths}개월 대조 / ${q.within1pct}개월 차이 1% 미만 · 제외 월: ${esc(q.excludedMonths.join(', ')||'없음')} · <a href="${esc(A.stockSources[c])}" target="_blank" rel="noopener">주가 원천</a></p>`).join('');$('channels').innerHTML=table(['설명지표','운영지표','시차','n','상관'],A.channels.map(c=>[esc(A.indicators[c.indicator].name),esc(A.indicators[c.target].name),c.lag,c.n,fmt(c.r)]));matrix();pair();}
load().catch(e=>{$('coverage').textContent=e.message;});
